graphql.query:
query cases ($after: String, $filter: CaseActivityLogFilter, $first: Int, $order: CaseActivityLogOrder, $after1: String, $filter1: CaseChildFilter, $first1: Int, $order1: CaseChildOrder, $after2: String, $filter2: CaseCommentFilter, $first2: Int, $order2: CaseCommentOrder, $after3: String, $filter3: CaseFilter, $first3: Int, $order3: CaseOrder) {
    cases (after: $after3, filter: $filter3, first: $first3, order: $order3) {
        edges {
            cursor
            node {
                activity (after: $after, filter: $filter, first: $first, order: $order) {
                    totalCount
                }
                aiSummary
                children (after: $after1, filter: $filter1, first: $first1, order: $order1) {
                    totalCount
                }
                childrenOverview {
                    totalChildren
                    totalClosed
                    totalInProgress
                    totalNew
                    totalOpen
                }
                closeCode
                closedAt
                comments (after: $after2, filter: $filter2, first: $first2, order: $order2) {
                    totalCount
                }
                createdAt
                createdBy {
                    email
                    fullName
                    id
                    serviceNowId
                }
                customer {
                    active
                    headerSlug
                    id
                    name
                    residency
                    slug
                }
                description
                discoverExposure {
                    aiSummary
                    description
                    exposure
                    id
                    mitigations
                    type
                }
                dueAt
                expirationDate
                id
                lastSummarizedAt
                owner {
                    email
                    fullName
                    id
                    serviceNowId
                }
                reasonForClosure
                severity
                slug
                state
                subType
                title
                type
                updatedAt
                updatedBy {
                    email
                    fullName
                    id
                    serviceNowId
                }
            }
        }
        pageInfo {
            endCursor
            hasNextPage
            hasPreviousPage
            startCursor
        }
        totalCount
    }
}

