mutation watchDRPAlert ($after: String, $filter: AccessGroupFilter, $first: Int, $order: AccessGroupOrder, $after1: String, $filter1: PodFilter, $first1: Int, $order1: PodOrder, $after2: String, $filter2: RoleFilter, $first2: Int, $order2: RoleFilter, $shortCode: String!) {
    watchDRPAlert (shortCode: $shortCode) {
        alert {
            active
            activityLogItems {
                actionKey
                clientId
                created
                payload
                permissions
                scope
            }
            alertFingerprint
            assetMatches {
                approvalState
                archivedState
                clientId
                created
                deleted
                id
                modified
                pending
                serialId
                status
                type
            }
            classification
            closedSource
            createdAt
            currentAssignment {
                timestamp
                version
            }
            currentFlag {
                timestamp
            }
            currentState {
                state
                timestamp
                version
            }
            currentWatcher {
                timestamp
            }
            customer {
                active
                headerSlug
                id
                name
                residency
                slug
            }
            domain
            hosts
            id
            migrated
            originator {
                originatorType
            }
            rejectedByRuleIds
            removedAt
            riskFactorKeys
            riskType
            severity
            shortCode
            sourceGroup
            sourceRef
            sourceUpdated
            sourceUris
            subTitle
            takedown {
                id
                state
            }
            thumbnailUri
            title
            updatedAt
            uri
        }
        id
        success
        timestamp
        user {
            accessGroups (after: $after, filter: $filter, first: $first, order: $order) {
                totalCount
            }
            email
            fullName
            id
            pods (after: $after1, filter: $filter1, first: $first1, order: $order1) {
                totalCount
            }
            roles (after: $after2, filter: $filter2, first: $first2, order: $order2) {
                totalCount
            }
            serviceNowId
        }
    }
}

