graphql.query:
query task ($after: String, $filter: TaskActivityLogFilter, $first: Int, $order: TaskActivityLogOrder, $after1: String, $filter1: AccessGroupFilter, $first1: Int, $order1: AccessGroupOrder, $after2: String, $filter2: PodFilter, $first2: Int, $order2: PodOrder, $after3: String, $filter3: RoleFilter, $first3: Int, $order3: RoleFilter, $after4: String, $filter4: TaskCommentFilter, $first4: Int, $order4: TaskCommentOrder, $after5: String, $filter5: AccessGroupFilter, $first5: Int, $order5: AccessGroupOrder, $after6: String, $filter6: PodFilter, $first6: Int, $order6: PodOrder, $after7: String, $filter7: RoleFilter, $first7: Int, $order7: RoleFilter, $after8: String, $first8: Int, $createdAfter: DateTime, $createdBefore: DateTime, $after9: String, $first9: Int, $after10: String, $filter8: AccessGroupFilter, $first10: Int, $order8: AccessGroupOrder, $after11: String, $filter9: PodFilter, $first11: Int, $order9: PodOrder, $after12: String, $filter10: RoleFilter, $first12: Int, $order10: RoleFilter, $by: TaskBy!) {
    task (by: $by) {
        acknowledgement {
            actionMethod
            createdAt
            user {
                email
                fullName
                id
                serviceNowId
            }
        }
        activity (after: $after, filter: $filter, first: $first, order: $order) {
            edges {
                cursor
            }
            pageInfo {
                endCursor
                hasNextPage
                hasPreviousPage
                startCursor
            }
        }
        assignee {
            accessGroups (after: $after1, filter: $filter1, first: $first1, order: $order1) {
                totalCount
            }
            email
            fullName
            id
            pods (after: $after2, filter: $filter2, first: $first2, order: $order2) {
                totalCount
            }
            roles (after: $after3, filter: $filter3, first: $first3, order: $order3) {
                totalCount
            }
            serviceNowId
        }
        closeCode
        closeNote
        closedAt
        comments (after: $after4, filter: $filter4, first: $first4, order: $order4) {
            edges {
                cursor
            }
            pageInfo {
                endCursor
                hasNextPage
                hasPreviousPage
                startCursor
            }
            totalCount
        }
        createdAt
        createdBy {
            accessGroups (after: $after5, filter: $filter5, first: $first5, order: $order5) {
                totalCount
            }
            email
            fullName
            id
            pods (after: $after6, filter: $filter6, first: $first6, order: $order6) {
                totalCount
            }
            roles (after: $after7, filter: $filter7, first: $first7, order: $order7) {
                totalCount
            }
            serviceNowId
        }
        customer {
            accessControlPolicies (after: $after8, first: $first8) {
                totalCount
            }
            active
            deployedRulesCount (createdAfter: $createdAfter, createdBefore: $createdBefore) {
                count
            }
            headerSlug
            id
            name
            residency
            slug
            users (after: $after9, first: $first9) {
                totalCount
            }
        }
        description
        externalId
        id
        metadata {
            ... on EngineeringTaskMetadata {
                businessCriticalLogSourceImpact
                businessCriticalLogSourceImpactReason
                changeWindowRequired
                engineeringTaskSubType
                environmentImpact
                errorMessagesObserved
                issue
                issueStartedAt
                logSourceNotListed
                logSources
                neededForCompliance
                neededForComplianceDetails
                recentLogSourceChangeDetails
                recentLogSourceChanges
                requiredMetadata
                retentionReason
                retentionRequirements
                supportTimeFrame
                troubleShootingDetails
                troubleShootingStarted
            }
        }
        priority
        retained
        serviceNowCategory
        serviceNowSubCategory
        slug
        state
        title
        type
        updatedAt
        updatedBy {
            accessGroups (after: $after10, filter: $filter8, first: $first10, order: $order8) {
                totalCount
            }
            email
            fullName
            id
            pods (after: $after11, filter: $filter9, first: $first11, order: $order9) {
                totalCount
            }
            roles (after: $after12, filter: $filter10, first: $first12, order: $order10) {
                totalCount
            }
            serviceNowId
        }
    }
}

